import type { ParsedIntentFile } from "../parser/intent.js";

const INTRO =
  "User intents of this project, anchored to the code. Generated by `@vaubaan/harness` from `docs/intents/*.md`: edit the intents, not this file, then run `npx @vaubaan/harness update .`.";

/**
 * `docs/intents/README.md`: every intent file (sorted by file name) and its
 * whole tree, one line per node with its effective status, the actors on
 * the level-1 intent line (docs/spec/coding-agent-harness.md §9.1.3).
 */
export function buildIntentsIndex(intentFiles: ReadonlyArray<ParsedIntentFile>): string {
  const lines = ["# Intents", "", INTRO, ""];
  const sorted = [...intentFiles].sort((a, b) => (a.file < b.file ? -1 : a.file > b.file ? 1 : 0));
  for (const intentFile of sorted) {
    const status = intentFile.meta?.status ?? "proposed";
    const actors = intentFile.meta?.actors.join(", ") ?? "";
    lines.push(`- [${intentFile.title}](./${intentFile.file}) — ${status} · ${actors}`);
    for (const node of intentFile.nodes) {
      lines.push(`${"  ".repeat(node.level)}- ${node.title} — ${node.effectiveStatus ?? status}`);
    }
  }
  return `${lines.join("\n")}\n`;
}
